create or replace function public.write_audit_log() returns trigger language plpgsql security definer set search_path=public as $$ declare v_actor uuid; v_entity_id uuid; v_before jsonb; v_after jsonb; begin v_actor:=auth.uid(); if TG_OP='INSERT' then v_entity_id:=NEW.id; v_after:=to_jsonb(NEW); elsif TG_OP='UPDATE' then v_entity_id:=NEW.id; v_before:=to_jsonb(OLD); v_after:=to_jsonb(NEW); else v_entity_id:=OLD.id; v_before:=to_jsonb(OLD); end if; insert into public.audit_logs(actor_id,action,entity_type,entity_id,before_data,after_data,metadata) values(v_actor,lower(TG_OP),TG_TABLE_NAME,v_entity_id,v_before,v_after,jsonb_build_object('source','database_trigger')); return coalesce(NEW,OLD); end; $$;
create or replace function public.audit_immutable() returns trigger language plpgsql security definer set search_path=public as $$ begin raise exception 'audit_logs is immutable'; end; $$;
drop trigger if exists audit_immutable_update on public.audit_logs; drop trigger if exists audit_immutable_delete on public.audit_logs; create trigger audit_immutable_update before update on public.audit_logs for each row execute function public.audit_immutable(); create trigger audit_immutable_delete before delete on public.audit_logs for each row execute function public.audit_immutable();
